#!/usr/bin/env python3

import csv
import os


# ============================================================
# PATHS
# ============================================================

BASE_DIR = "/home/fady/IoT-devices"

# Packet features generated by TrafficMonitor
PACKET_CSV = os.path.join(
    BASE_DIR,
    "pcap_packet_features_v2.csv"
)

# Attack metadata generated by attack_manager
METADATA_CSV = os.path.join(
    BASE_DIR,
    "datasets",
    "metadata",
    "attack_metadata.csv"
)

# Final labeled dataset
OUTPUT_CSV = os.path.join(
    BASE_DIR,
    "labeled_packet_features.csv"
)


# ============================================================
# PROTOCOL MAPPING
# ============================================================

PROTOCOL_MAP = {
    "TCP": 6,
    "UDP": 17,
    "ICMP": 1
}


# ============================================================
# LOAD ATTACK METADATA
# ============================================================

def load_attack_metadata():

    attacks = []

    with open(
        METADATA_CSV,
        mode="r",
        newline=""
    ) as file:

        reader = csv.DictReader(file)

        for row in reader:

            attacks.append({
                "run_id": row["run_id"],
                "attack_type": row["attack_type"],

                "start_timestamp":
                    float(row["start_timestamp"]),

                "end_timestamp":
                    float(row["end_timestamp"]),

                "src_ip": row["src_ip"],
                "dst_ip": row["dst_ip"],

                "src_port": row["src_port"],
                "dst_port": row["dst_port"],

                "protocol": row["protocol"]
            })

    return attacks


# ============================================================
# CHECK WHETHER PACKET MATCHES ATTACK
# ============================================================

def packet_matches_attack(packet, attack):

    # --------------------------------------------------------
    # 1. Timestamp
    # --------------------------------------------------------

    packet_timestamp = float(
        packet["timestamp"]
    )

    if not (
        attack["start_timestamp"]
        <= packet_timestamp
        <= attack["end_timestamp"]
    ):
        return False


    # --------------------------------------------------------
    # 2. Source IP
    # --------------------------------------------------------

    if attack["src_ip"] != "*":

        if packet["src_ip"] != attack["src_ip"]:
            return False


    # --------------------------------------------------------
    # 3. Destination IP
    # --------------------------------------------------------

    if attack["dst_ip"] != "*":

        if packet["dst_ip"] != attack["dst_ip"]:
            return False


    # --------------------------------------------------------
    # 4. Source Port
    # --------------------------------------------------------

    if attack["src_port"] != "*":

        if str(packet["src_port"]) != attack["src_port"]:
            return False


    # --------------------------------------------------------
    # 5. Destination Port
    # --------------------------------------------------------

    if attack["dst_port"] != "*":

        if str(packet["dst_port"]) != attack["dst_port"]:
            return False


    # --------------------------------------------------------
    # 6. Protocol
    # --------------------------------------------------------

    protocol = attack["protocol"].upper()

    if protocol in PROTOCOL_MAP:

        expected_protocol = PROTOCOL_MAP[protocol]

        if int(packet["ip_proto"]) != expected_protocol:
            return False


    return True


# ============================================================
# FIND PACKET LABEL
# ============================================================

def get_packet_label(packet, attacks):

    for attack in attacks:

        if packet_matches_attack(
            packet,
            attack
        ):

            return (
                attack["attack_type"],
                attack["run_id"]
            )

    return (
        "normal",
        ""
    )


# ============================================================
# PREPARE LABELED DATASET
# ============================================================

def prepare_dataset():

    print()
    print("==============================================")
    print("        DATASET PREPARATION")
    print("==============================================")
    print()

    print(
        "Packet CSV   :",
        PACKET_CSV
    )

    print(
        "Metadata CSV :",
        METADATA_CSV
    )

    print(
        "Output CSV   :",
        OUTPUT_CSV
    )

    print()


    # --------------------------------------------------------
    # Check Packet CSV
    # --------------------------------------------------------

    if not os.path.exists(PACKET_CSV):

        print(
            "ERROR: packet_features.csv not found."
        )

        print(
            "Expected path:",
            PACKET_CSV
        )

        return


    # --------------------------------------------------------
    # Check Metadata CSV
    # --------------------------------------------------------

    if not os.path.exists(METADATA_CSV):

        print(
            "ERROR: attack_metadata.csv not found."
        )

        print(
            "Expected path:",
            METADATA_CSV
        )

        return


    # --------------------------------------------------------
    # Load Attack Metadata
    # --------------------------------------------------------

    attacks = load_attack_metadata()

    print(
        "Attack metadata loaded:",
        len(attacks)
    )

    print()


    # --------------------------------------------------------
    # Read Packet CSV
    # --------------------------------------------------------

    with open(
        PACKET_CSV,
        mode="r",
        newline=""
    ) as input_file:

        reader = csv.DictReader(input_file)

        fieldnames = reader.fieldnames

        if fieldnames is None:

            print(
                "ERROR: packet_features.csv is empty."
            )

            return


        # ----------------------------------------------------
        # Add Label Columns
        # ----------------------------------------------------

        output_fields = list(fieldnames)

        output_fields.append("label")


        # ----------------------------------------------------
        # Create Output CSV
        # ----------------------------------------------------

        with open(
            OUTPUT_CSV,
            mode="w",
            newline=""
        ) as output_file:

            writer = csv.DictWriter(
                output_file,
                fieldnames=output_fields
            )

            writer.writeheader()


            # ------------------------------------------------
            # Counters
            # ------------------------------------------------

            total_packets = 0
            attack_packets = 0
            normal_packets = 0


            # ------------------------------------------------
            # Process Every Packet
            # ------------------------------------------------

            for packet in reader:

                total_packets += 1

                label, run_id = get_packet_label(
                    packet,
                    attacks
                )

                packet["label"] = label
                packet["run_id"] = run_id

                writer.writerow(packet)


                if label == "normal":

                    normal_packets += 1

                else:

                    attack_packets += 1


    # --------------------------------------------------------
    # Summary
    # --------------------------------------------------------

    print("==============================================")
    print("        DATASET PREPARATION COMPLETE")
    print("==============================================")

    print(
        "Total packets   :",
        total_packets
    )

    print(
        "Attack packets  :",
        attack_packets
    )

    print(
        "Normal packets  :",
        normal_packets
    )

    print()

    print(
        "Output dataset  :",
        OUTPUT_CSV
    )

    print("==============================================")
    print()


# ============================================================
# MAIN
# ============================================================

if __name__ == "__main__":

    prepare_dataset()
